Case 1: os.Args
Save as raw_args.go. Print every argument after the program name.
// raw_args.go
package main

import (
    "fmt"
    "os"
)

func main() {
    if len(os.Args) &lt; 2 {
        fmt.Fprintln(os.Stderr, "usage: raw_args &lt;name&gt;")
        os.Exit(1)
